// Navigation Bar Component — connected to CartContext, working search
import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useCart } from '../../context/CartContext';
import { useLanguage } from '../../context/LanguageContext';
import MobileBottomNav from './MobileBottomNav';

export const NavigationBar = ({ theme = 'light', onToggleTheme }) => {
  const navigate = useNavigate();
  const { cartCount } = useCart();
  const { t } = useLanguage();
  const [searchQuery, setSearchQuery] = useState('');
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [user, setUser] = useState(null);

  // BigBasket Style States
  const [showLocationMenu, setShowLocationMenu] = useState(false);
  const [city, setCity] = useState(localStorage.getItem('selectedCity') || 'Bangalore');

  useEffect(() => {
    try {
      const storedUser = localStorage.getItem('authUser');
      setUser(storedUser ? JSON.parse(storedUser) : null);
    } catch (_) {
      setUser(null);
    }
  }, []);

  useEffect(() => {
    const syncUser = () => {
      try {
        const storedUser = localStorage.getItem('authUser');
        setUser(storedUser ? JSON.parse(storedUser) : null);
      } catch (_) {
        setUser(null);
      }
    };

    window.addEventListener('auth-change', syncUser);
    window.addEventListener('storage', syncUser);
    return () => {
      window.removeEventListener('auth-change', syncUser);
      window.removeEventListener('storage', syncUser);
    };
  }, []);

  const locationRef = React.useRef(null);
  const userMenuRef = React.useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (locationRef.current && !locationRef.current.contains(event.target)) {
        setShowLocationMenu(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
        setShowUserMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('touchstart', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('touchstart', handleClickOutside);
    };
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('authUser');
    setShowUserMenu(false);
    window.dispatchEvent(new Event('auth-change'));
    navigate('/');
  };

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      navigate(`/products?search=${encodeURIComponent(searchQuery.trim())}`);
      setSearchQuery('');
    }
  };

  const handleCitySelect = (cityName) => {
    setCity(cityName);
    localStorage.setItem('selectedCity', cityName);
    setShowLocationMenu(false);
  };

  return (
    <>
      <nav className="navbar">
        <div className="navbar-container">
          <div className="navbar-brand-group">
            <div className="logo">
              <Link to="/" style={{ textDecoration: 'none', color: 'inherit', display: 'flex', alignItems: 'center', gap: '4px' }}>
                <span className="logo-mega">mega</span>
                <span className="logo-mart">mart</span>
                <span className="logo-icon">🌿</span>
              </Link>
            </div>

            {/* Location Selector */}
            <div className="location-selector" ref={locationRef}>
              <button
                type="button"
                className="location-btn"
                onClick={() => setShowLocationMenu(!showLocationMenu)}
                aria-label={`Select location, current: ${city}`}
              >
                <span className="loc-pin">📍</span>
                <span className="loc-name">{city}</span>
                <span className="loc-arrow">▾</span>
              </button>
              {showLocationMenu && (
                <div className="location-dropdown">
                  <div className="location-dropdown-title">Select Delivery City</div>
                  {['Bangalore', 'Mumbai', 'Delhi', 'Hyderabad', 'Pune', 'Chennai', 'Kolkata'].map((cityName) => (
                    <button
                      type="button"
                      key={cityName}
                      className={cityName === city ? 'active' : ''}
                      onClick={() => handleCitySelect(cityName)}
                    >
                      {cityName} {cityName === city ? '✓' : ''}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="navbar-actions">
            <button
              className="action-icon theme-toggle"
              title="Toggle theme"
              onClick={onToggleTheme}
              type="button"
            >
              {theme === 'dark' ? '☀️' : '🌙'}
            </button>

            {user ? (
              <div className="user-menu" ref={userMenuRef}>
                <button
                  className="action-icon user-name"
                  onClick={() => setShowUserMenu(!showUserMenu)}
                  title="Account"
                >
                  <span className="user-avatar-icon">👤</span>
                  <span className="nav-action-text">{user.name.split(' ')[0]}</span>
                </button>
                {showUserMenu && (
                  <div className="user-dropdown">
                    <div className="user-dropdown-header">
                      <strong>{user.name}</strong>
                      <small>{user.email || ''}</small>
                    </div>
                    <Link to="/products" onClick={() => setShowUserMenu(false)}>{t('myProducts')}</Link>
                    <Link to="/order-tracking" onClick={() => setShowUserMenu(false)}>{t('myOrders')}</Link>
                    <button onClick={handleLogout} className="logout-btn">{t('signOut')}</button>
                  </div>
                )}
              </div>
            ) : (
              <Link className="action-icon sign-in-btn" to="/login" title="Sign In">
                <span className="user-avatar-icon">👤</span>
                <span className="nav-action-text">{t('signIn')}</span>
              </Link>
            )}

            <Link className="action-icon cart desktop-only-action" to="/cart" title="Cart">
              🛒{' '}
              {cartCount > 0 && <span className="badge">{cartCount}</span>}
            </Link>

            <Link className="action-icon wishlist desktop-only-action" to="/wishlist" title="Wishlist">
              ❤️
            </Link>
          </div>

          <form className="search-container" onSubmit={handleSearch}>
            <span className="search-lead-icon">🔍</span>
            <input
              type="text"
              placeholder="Search groceries, essentials, items..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              aria-label="Search products"
            />
            {searchQuery && (
              <button
                type="button"
                className="search-clear-btn"
                onClick={() => setSearchQuery('')}
                title="Clear search"
              >
                ✕
              </button>
            )}
            <button type="submit" className="search-btn" aria-label="Submit search">
              <span>Search</span>
            </button>
          </form>
        </div>
      </nav>
      <MobileBottomNav />
    </>
  );
};

export default NavigationBar;
